)

# All wrappers share one help page. Each individual function is exported
# and can be looked up directly, e.g. ?get_client or ?get_worksheet.
header <- c(
  "# Generated by data-raw/generate-endpoint-wrappers.R. Do not edit by hand.",
  "",
  "#' Retrieve data from a named SENAITE endpoint",
  "#'",
  "#' Each wrapper calls [get_senaite_data()] with a fixed endpoint name.",
  "#' For example, `get_client()` queries the `client` endpoint.",
  "#' The selected profile supplies the instance URL and credentials.",
  "#'",
  "#' @inheritParams get_senaite_data",
  "#' @returns A list of records, or an empty list for an empty collection.",
  "#'   As with [get_senaite_data()], a successful response without a `pages`",
  "#'   field returns `NULL`. HTTP errors raise an error.",
  "#' @examples",
  "#' \\dontrun{",
  "#' clients <- get_client(profile = \"lab-lan\")",
  "#'",
  "#' verified <- get_analysisrequest(",
  "#'   params = list(review_state = \"verified\"),",
  "#'   limit = 50,",
  "#'   profile = \"lab-lan\"",
  "#' )",
  "#' }",
  "#' @seealso [get_senaite_data()], [senaite_setup()]",
  "#' @name senaite_endpoints",
  "NULL",
  ""
)

make_wrapper <- function(endpoint) {
  c(
    "#' @rdname senaite_endpoints",
    "#' @export",
    sprintf("get_%s <- function(params = list(), limit = 100,", endpoint),
    "                         verbose = TRUE, profile = \"default\") {",
    "  get_senaite_data(",
    sprintf("    endpoint = \"%s\",", endpoint),
    "    params = params,",
    "    limit = limit,",
    "    verbose = verbose,",
    "    profile = profile",
    "  )",
    "}",
    ""
  )
}

output <- file.path("R", "senaite-endpoints.R")
lines <- c(header, unlist(lapply(endpoints, make_wrapper), use.names = FALSE))

# Check the generated R syntax before replacing the output file.
invisible(parse(text = lines))
writeLines(lines, output)

message("Wrote ", length(endpoints), " endpoint wrappers to ", output)
